ValidationRule.errorConditionFormula:
AND(
 NOT(
  AND(Is_Auto_Approval_Allowed__c,
   ISCHANGED(Is_Auto_Approval_Allowed__c)
  )
 ),
 NOT(
  AND(ISCHANGED(OwnerId),ISPICKVAL( Status ,'Under Review'))
 ),
 AND(
  ISCHANGED(Status),
  NOT(ISPICKVAL(Status,'Submitted')),
  NOT(
   OR(
    Contains($Profile.Name,"System Administrator"),
    Contains($Profile.Name,"Board Staff"),
    AND(Contains($Profile.Name,"Support Staff"),ISPICKVAL(ApplicationType,'Renewal'))				
   )
  )
 )
)
